using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Collections.Generic;
using System.Security.Cryptography;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using LighFight.Runtime;
// Review-only direct-original rotations. NO retarget fallback and NO production/catalog writes.
public static class IslandNativeFistCompareJob {
 const string Folder="Assets/IslandNativeStrikeReview";
 const string SHA="5cc8b7208f3267cb1e20909bcff4eb04a9b9bf58ce7f28ebb77bbdb516c41a24";
 const float Epsilon=0.000001f;
 [Serializable] public sealed class Candidate {public string sourceSHA256,take;public float sourceSeconds=-1;}
 [Serializable] sealed class Report {public string status,sourceSHA256,targetModel,sourceCurveHash,candidateJsonSHA,fullRenderAttributeHash;public float sourceSeconds,maximumBodyVertexError,sourceCaptureSurfaceError,maximumNonFingerLocalError;public int fingerJoints,bodyVertices,handWeightedVertices;public bool sourceUnchanged,accepted;}
 struct Local {public Vector3 p,s;public Quaternion q;public Local(Transform t){p=t.localPosition;s=t.localScale;q=t.localRotation;}public float Error(Transform t)=>Mathf.Max(Vector3.Distance(p,t.localPosition),Mathf.Max(Vector3.Distance(s,t.localScale),QuaternionError(q,t.localRotation)));}
 static float QuaternionError(Quaternion a,Quaternion b){float sign=Quaternion.Dot(a,b)<0?-1:1;return Mathf.Max(Mathf.Abs(a.x-sign*b.x),Mathf.Max(Mathf.Abs(a.y-sign*b.y),Mathf.Max(Mathf.Abs(a.z-sign*b.z),Mathf.Abs(a.w-sign*b.w))));}
 static string Arg(string k){var a=Environment.GetCommandLineArgs();int i=Array.IndexOf(a,k);if(i<0||i+1>=a.Length)throw new Exception("Required "+k);return a[i+1];}
 static string Hash(byte[] b){using(var s=SHA256.Create())return BitConverter.ToString(s.ComputeHash(b)).Replace("-","").ToLowerInvariant();}
 static void Require(bool ok,string message){if(!ok)throw new InvalidOperationException(message);}
 static void Owned(){string root=Path.GetFullPath(Path.GetDirectoryName(Application.dataPath));Require(root.Replace(Path.DirectorySeparatorChar,'/').Contains("/.tools/tripo-humanoid-review-unity/"),"Owned QA project only; main forbidden");Directory.SetCurrentDirectory(root);Directory.CreateDirectory("IslandStrikeEvidence/Fist");}
 [Serializable] sealed class Blocked {public string status="BLOCKED_NOT_ACCEPTED",error;public bool accepted=false;}
 public static void Run(){Owned();try{RunChecked();}catch(Exception e){string blocked=JsonUtility.ToJson(new Blocked{error=e.ToString()},true);File.WriteAllText("IslandStrikeEvidence/Fist/blocked.json",blocked);File.WriteAllText("IslandStrikeEvidence/Fist/gates.json",blocked);throw;}}
 static void RunChecked(){
  Owned();string targetPath=Arg("-islandTargetModel"),sdkPath=Arg("-islandSdkFist"),candidatePath=Arg("-islandFistCandidate");byte[] candidateBytes=File.ReadAllBytes(candidatePath);string candidateText=Encoding.UTF8.GetString(candidateBytes);Require(candidateText.Contains("\"sourceSeconds\""),"Explicit sourceSeconds property missing");var candidate=JsonUtility.FromJson<Candidate>(candidateText);Require(candidate!=null&&float.IsFinite(candidate.sourceSeconds)&&candidate.sourceSHA256==SHA&&candidate.take=="box_02"&&candidate.sourceSeconds>=0&&candidate.sourceSeconds<=67f/24,"Explicit sourceSHA256/take/sourceSeconds candidate required; never inferred or accepted automatically");
  string genericPath=Folder+"/Source/model.fbx";Require(Hash(File.ReadAllBytes(genericPath))==SHA&&Hash(File.ReadAllBytes(targetPath))==SHA,"Source and target FBX bytes must both equal exact native source");var rawModel=AssetDatabase.LoadAssetAtPath<GameObject>(genericPath);var targetModel=AssetDatabase.LoadAssetAtPath<GameObject>(targetPath);var sdk=AssetDatabase.LoadAssetAtPath<NativeFingerPose>(sdkPath);var material=AssetDatabase.LoadAssetAtPath<Material>(Arg("-islandReviewMaterial"));Require(material,"Copied source PBR review material required");Require(rawModel&&targetModel&&sdk,"Missing prepared raw model, copied calibrated target, or copied SDK fist");
  using(var frozen=IslandRenderAttributeIdentity.Freeze(sdkPath,material,"IslandStrikeEvidence/Fist")){
  var avatar=AssetDatabase.LoadAllAssetsAtPath(targetPath).OfType<Avatar>().Single(x=>x.isValid&&x.isHuman);Require(sdk.sourceAvatar==avatar&&sdk.joints.Length==30,"Existing SDK fist must belong to this exact target Avatar, with thirty joints");
  var source=UnityEngine.Object.Instantiate(rawModel);var target=UnityEngine.Object.Instantiate(targetModel);Mesh bakeSource=new Mesh(),bakeTarget=new Mesh();IDisposable lease=null;
  try{
   foreach(var x in source.GetComponentsInChildren<Animator>())x.enabled=false;foreach(var x in target.GetComponentsInChildren<Animator>())x.enabled=false;
   var a=source.GetComponentInChildren<SkinnedMeshRenderer>();var b=target.GetComponentInChildren<SkinnedMeshRenderer>();string meshHash=IslandNativeStrikeReviewJob.MeshHash(a.sharedMesh);string renderHash=IslandRenderAttributeIdentity.FullMeshHash(a.sharedMesh);Require(renderHash==IslandRenderAttributeIdentity.FullMeshHash(b.sharedMesh),"Exact full imported render attributes/submesh layout mismatch; no transfer or normal recalculation");Require(meshHash==IslandNativeStrikeReviewJob.MeshHash(b.sharedMesh),"Exact stored geometry/UV/topology/bind/weights mismatch; no transfer");
   var rawPaths=a.bones.Select(x=>AnimationUtility.CalculateTransformPath(x,source.transform)).ToArray();var targetPaths=b.bones.Select(x=>AnimationUtility.CalculateTransformPath(x,target.transform)).ToArray();Require(rawPaths.SequenceEqual(targetPaths)&&rawPaths.Length==67,"Exact native bone order/path gate failed");
   // Verify every local frame, not just bone names or T-pose silhouette.
   var rest=source.GetComponentsInChildren<Transform>().ToDictionary(x=>AnimationUtility.CalculateTransformPath(x,source.transform),x=>new Local(x));Require(new HashSet<string>(rest.Keys).SetEquals(target.GetComponentsInChildren<Transform>().Select(x=>AnimationUtility.CalculateTransformPath(x,target.transform))),"Exact full native hierarchy paths differ");foreach(var pair in rest){var t=pair.Key.Length==0?target.transform:target.transform.Find(pair.Key);Require(t&&pair.Value.Error(t)<=Epsilon,"Original local frame incompatible: "+pair.Key);}
   var anim=target.GetComponent<Animator>();Require(anim&&anim.avatar==avatar,"Target model own calibrated Avatar missing");var fingerTransforms=new List<Transform>();for(int i=(int)HumanBodyBones.LeftThumbProximal;i<=(int)HumanBodyBones.RightLittleDistal;i++)fingerTransforms.Add(anim.GetBoneTransform((HumanBodyBones)i));Require(fingerTransforms.Count==30&&fingerTransforms.All(x=>x)&&fingerTransforms.Distinct().Count()==30,"Target avatar must map all thirty unique finger transforms");var fingerPaths=fingerTransforms.Select(x=>AnimationUtility.CalculateTransformPath(x,target.transform)).ToArray();Require(new HashSet<string>(fingerPaths).SetEquals(sdk.joints.Select(x=>x.path)),"SDK path set differs from avatar-mapped fingers");foreach(string p in fingerPaths)Require(rest.ContainsKey(p)&&source.transform.Find(p),"Native raw finger path missing: "+p);
   var clip=AssetDatabase.LoadAllAssetsAtPath(genericPath).OfType<AnimationClip>().Single(x=>x.name==candidate.take&&!x.humanMotion);var data=AssetDatabase.LoadAssetAtPath<NativeSupportPoseData>(Folder+"/Poses/box_02.pose.asset");Require(data&&data.PackedAsset&&data.sourceName==clip.name&&Mathf.Abs(data.duration-clip.length)<1e-5f&&data.sourceCurveHash.Length==64,"Run exact original Generic export/lossless Prepare first");lease=data.PinAndPrewarm();var bound=data.Bind(target.transform);
   clip.SampleAnimation(source,candidate.sourceSeconds);data.Apply(bound,candidate.sourceSeconds);float captureError=SurfaceError(a,b,bakeSource,bakeTarget,null);Require(captureError<=.00001f,"Target/source original FK surface mismatch at capture");
   var joints=new NativeFingerPose.Joint[30];for(int i=0;i<30;i++){var native=source.transform.Find(fingerPaths[i]);var r=rest[fingerPaths[i]];Require(Vector3.Distance(r.p,native.localPosition)<=Epsilon&&Vector3.Distance(r.s,native.localScale)<=Epsilon,"Native finger has animated translation/scale; rotation-only transfer disallowed: "+fingerPaths[i]);joints[i]=new NativeFingerPose.Joint{path=fingerPaths[i],rotation=native.localRotation};}
   string resultPath=Folder+"/NativeFistCandidate.UNACCEPTED.asset";var proposed=AssetDatabase.LoadAssetAtPath<NativeFingerPose>(resultPath);if(!proposed){proposed=ScriptableObject.CreateInstance<NativeFingerPose>();AssetDatabase.CreateAsset(proposed,resultPath);}proposed.sourceAvatar=avatar;proposed.sourceClip="UNACCEPTED source Generic box_02, exact native local frame gates passed";proposed.sourceSeconds=candidate.sourceSeconds;proposed.joints=joints;EditorUtility.SetDirty(proposed);
   var selected=new HashSet<int>(Enumerable.Range(0,b.bones.Length).Where(i=>fingerPaths.Any(p=>targetPaths[i]==p||targetPaths[i].StartsWith(p+"/",StringComparison.Ordinal))));var body=BodyMask(b.sharedMesh,selected);float maxBody=0,maxLocal=0;
   using(var log=new StreamWriter("IslandStrikeEvidence/Fist/surface-comparison.csv")){log.WriteLine("sourceSeconds,variant,fullSurfaceDifferenceFromOriginal,bodyVertexMaxError,nonFingerLocalMaxError");int count=Mathf.CeilToInt(data.duration*240);for(int step=0;step<=count;step++){float t=Mathf.Min(step/240f,data.duration);clip.SampleAnimation(source,t);foreach(var variant in new[]{sdk,proposed}){data.Apply(bound,t);var before=target.GetComponentsInChildren<Transform>().Where(x=>!fingerPaths.Contains(AnimationUtility.CalculateTransformPath(x,target.transform))).ToDictionary(x=>x,x=>new Local(x));foreach(var j in variant.joints)target.transform.Find(j.path).localRotation=j.rotation;float local=before.Max(x=>x.Value.Error(x.Key));float bodyError=SurfaceError(a,b,bakeSource,bakeTarget,body),fullError=SurfaceError(a,b,bakeSource,bakeTarget,null);Require(local<=Epsilon&&bodyError<=.00001f,"Finger-only experiment changed body/clothing or nonfinger local transform");maxBody=Mathf.Max(maxBody,bodyError);maxLocal=Mathf.Max(maxLocal,local);log.WriteLine(FormattableString.Invariant($"{t:R},{(variant==sdk?"existingSDK":"sourceNativeCandidate")},{fullError:R},{bodyError:R},{local:R}"));}}}
   Require(IslandRenderAttributeIdentity.FullMeshHash(a.sharedMesh)==renderHash&&IslandRenderAttributeIdentity.FullMeshHash(b.sharedMesh)==renderHash,"Stored render attributes mutated during finger comparison");Require(IslandNativeStrikeReviewJob.MeshHash(a.sharedMesh)==meshHash&&IslandNativeStrikeReviewJob.MeshHash(b.sharedMesh)==meshHash&&Hash(File.ReadAllBytes(targetPath))==SHA&&Hash(File.ReadAllBytes(genericPath))==SHA,"Source mesh/native FBX mutated");AssetDatabase.SaveAssets();File.WriteAllText("IslandStrikeEvidence/Fist/gates.json",JsonUtility.ToJson(new Report{status="LOCAL_FRAME_AND_FINGER_ONLY_GATES_PASSED_NOT_VISUAL_OR_GAMEPLAY_ACCEPTED",sourceSHA256=SHA,targetModel=targetPath,fullRenderAttributeHash=renderHash,sourceCurveHash=data.sourceCurveHash,candidateJsonSHA=Hash(candidateBytes),sourceSeconds=candidate.sourceSeconds,maximumBodyVertexError=maxBody,maximumNonFingerLocalError=maxLocal,sourceCaptureSurfaceError=captureError,fingerJoints=30,bodyVertices=body.Count(x=>x),handWeightedVertices=body.Count(x=>!x),sourceUnchanged=true,accepted=false},true));
   // EOF probe reproduces same source-body condition. All gameplay drivers remain outside this diagnostic.
   var controller=AssetDatabase.LoadAssetAtPath<RuntimeAnimatorController>(Folder+"/original-generic.controller");Require(controller,"Prepared original controller missing");var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var host=new GameObject("Island source-native versus SDK finger ONLY EOF review");var probe=host.AddComponent<IslandFistEOFProbe>();probe.rawModel=rawModel;probe.targetModel=targetModel;probe.originalController=controller;probe.pose=data;probe.sdk=sdk;probe.native=proposed;probe.bodyVertices=body;probe.reviewMaterial=material;EditorSceneManager.SaveScene(scene,Folder+"/fist-eof-review.unity");AssetDatabase.SaveAssets();Debug.Log("ISLAND_FIST local compatibility passed; source-native candidate created only for review. Actual thumb/seams/contact/EOF/GPU gates PENDING.");
  }finally{lease?.Dispose();UnityEngine.Object.DestroyImmediate(bakeSource);UnityEngine.Object.DestroyImmediate(bakeTarget);UnityEngine.Object.DestroyImmediate(source);UnityEngine.Object.DestroyImmediate(target);}
 }
 }
 static bool[] BodyMask(Mesh m,HashSet<int> fingers){var mask=Enumerable.Repeat(true,m.vertexCount).ToArray();using(var counts=m.GetBonesPerVertex())using(var weights=m.GetAllBoneWeights()){int cursor=0;for(int v=0;v<mask.Length;v++)for(int i=0;i<counts[v];i++){var w=weights[cursor++];if(w.weight>0&&fingers.Contains(w.boneIndex))mask[v]=false;}}return mask;}
 static float SurfaceError(SkinnedMeshRenderer a,SkinnedMeshRenderer b,Mesh x,Mesh y,bool[] mask){a.BakeMesh(x,true);b.BakeMesh(y,true);var av=x.vertices;var bv=y.vertices;Require(av.Length==bv.Length,"Vertex correspondence lost");float error=0;for(int i=0;i<av.Length;i++){if(mask!=null&&!mask[i])continue;float e=Vector3.Distance(a.transform.TransformPoint(av[i]),b.transform.TransformPoint(bv[i]));Require(float.IsFinite(e),"Nonfinite surface");error=Mathf.Max(error,e);}return error;}
 public static void BuildProbe(){Owned();string output=Arg("-islandFistPlayer");var r=BuildPipeline.BuildPlayer(new BuildPlayerOptions{scenes=new[]{Folder+"/fist-eof-review.unity"},locationPathName=output,target=BuildTarget.StandaloneOSX,options=BuildOptions.Development});Require(r.summary.result==UnityEditor.Build.Reporting.BuildResult.Succeeded,"Fist EOF probe build failed");}
}
